package vn.edu.crs.authservice.controller; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import vn.edu.crs.authservice.dto.*; import vn.edu.crs.authservice.repository.UserRepository; import vn.edu.crs.authservice.security.JwtUtil;
@RestController @RequestMapping("/auth") @RequiredArgsConstructor public class AuthController{final UserRepository r;final PasswordEncoder e;final JwtUtil j;@PostMapping("/login")public LoginResponse login(@Valid @RequestBody LoginRequest q){var u=r.findByUsername(q.getUsername()).orElseThrow(()->new RuntimeException("Sai username hoac password"));if(!e.matches(q.getPassword(),u.getPassword()))throw new RuntimeException("Sai username hoac password");return new LoginResponse(u.getId(),j.generate(u.getId(),u.getUsername(),u.getRole()),u.getUsername(),u.getRole());}}
